function esc(v) {
    return String(v == null ? "" : v).replace(/'/g, "''");
}

function body(p) {
    if (typeof p === "string") {
        try {
            return JSON.parse(p);
        } catch (e) {
            return { rfid_uid: p };
        }
    }

    return p || {};
}

function uid(v) {
    return String(v == null ? "" : v).trim().toUpperCase().replace(/\s+/g, "");
}

var b = body(msg.payload);
var scannedUid = uid(b.rfid_uid || b.uid || b.card_uid);

if (!scannedUid) {
    node.warn("RFID scan payload missing rfid_uid: " + JSON.stringify(b));
    return [null, { payload: "RFID scan without UID" }, null];
}

flow.set("latest_uid", scannedUid);

var displayMsg = {
    payload: {
        rfid_uid: scannedUid,
        source: b.source || "rfid-reader",
        timestamp: b.timestamp || new Date().toISOString()
    }
};

var checkMsg = {
    sp: {
        flow: "scan_check",
        rfid_uid: scannedUid,
        source: b.source || "rfid-reader"
    },
    topic: "SELECT id FROM user_admins WHERE rfid_uid='" + esc(scannedUid) + "' AND active=1 LIMIT 1"
};

return [displayMsg, { payload: "RFID scanned: " + scannedUid }, checkMsg];

function esc(v) {
    return String(v == null ? "" : v).replace(/'/g, "''");
}

function uid(v) {
    return String(v == null ? "" : v).trim().toUpperCase().replace(/\s+/g, "");
}

function status(text) {
    return { payload: text };
}

var action = msg.topic || msg.payload;
var latestUid = uid(flow.get("latest_uid"));

if (action === "register") {
    if (!latestUid) {
        return [null, status("Scan an RFID card before registering a UID.")];
    }

    msg.sp = {
        flow: "register_find",
        rfid_uid: latestUid,
        name: "RFID Admin"
    };
    msg.topic = "SELECT id FROM user_admins WHERE rfid_uid='" + esc(latestUid) + "' LIMIT 1";
    return [msg, status("Registering UID " + latestUid + "...")];
}

if (action === "revoke") {
    if (!latestUid) {
        return [null, status("Scan an RFID card before revoking a UID.")];
    }

    msg.sp = {
        flow: "revoke_done",
        rfid_uid: latestUid
    };
    msg.topic = "UPDATE user_admins SET active=0 WHERE rfid_uid='" + esc(latestUid) + "'";
    return [msg, status("Revoking UID " + latestUid + "...")];
}

if (action === "refresh") {
    msg.sp = { flow: "list_uids" };
    msg.topic = "SELECT rfid_uid,role,active FROM user_admins ORDER BY active DESC,rfid_uid";
    return [msg, status("Refreshing registered UID list...")];
}

return [null, status("Unknown RFID action: " + action)];

function esc(v) {
    return String(v == null ? "" : v).replace(/'/g, "''");
}

function isRows(v) {
    return Object.prototype.toString.call(v) === "[object Array]";
}

function status(text) {
    return { payload: text };
}

function listQuery() {
    return {
        sp: { flow: "list_uids" },
        topic: "SELECT rfid_uid,role,active FROM user_admins ORDER BY active DESC,rfid_uid"
    };
}

function servoCommand(command, rfidUid) {
    return {
        payload: {
            command: command,
            rfid_uid: rfidUid,
            source: "rfid-control-flow"
        }
    };
}

var rows = isRows(msg.payload) ? msg.payload : [];
var sp = msg.sp || {};

if (sp.flow === "scan_check") {
    if (rows.length < 1) {
        return [null, null, status("UID not registered: " + sp.rfid_uid), null];
    }

    var currentState = String(flow.get("servo_state") || "CLOSED");
    var nextCommand = currentState === "OPEN" ? "CLOSE" : "OPEN";
    var nextState = nextCommand === "OPEN" ? "OPEN" : "CLOSED";

    flow.set("servo_state", nextState);

    return [
        null,
        null,
        status("Registered UID " + sp.rfid_uid + " -> " + nextCommand),
        servoCommand(nextCommand, sp.rfid_uid)
    ];
}

if (sp.flow === "register_find") {
    if (rows.length > 0) {
        msg.sp = {
            flow: "register_done",
            rfid_uid: sp.rfid_uid,
            mode: "updated"
        };
        msg.topic = "UPDATE user_admins SET name='RFID Admin', role='admin', active=1 WHERE rfid_uid='" + esc(sp.rfid_uid) + "'";
        return [msg, null, null, null];
    }

    msg.sp = {
        flow: "register_done",
        rfid_uid: sp.rfid_uid,
        mode: "inserted"
    };
    msg.topic = "INSERT INTO user_admins(name,rfid_uid,role,active) VALUES('RFID Admin','" + esc(sp.rfid_uid) + "','admin',1)";
    return [msg, null, null, null];
}

if (sp.flow === "register_done") {
    return [
        listQuery(),
        null,
        status("UID " + sp.rfid_uid + " registered (" + sp.mode + ")."),
        null
    ];
}

if (sp.flow === "revoke_done") {
    return [
        listQuery(),
        null,
        status("UID " + sp.rfid_uid + " revoked."),
        null
    ];
}

if (sp.flow === "list_uids" || sp.flow === "list_admins") {
    msg.payload = rows;
    return [null, msg, status("Loaded " + rows.length + " registered UIDs."), null];
}

node.warn("Unhandled RFID control DB step: " + JSON.stringify(sp));
return null;
